'use strict';
const F=window.QLAFinance,KEY='qla-deal-lab-v1';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'Missing':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const ratio=v=>v==null?'No debt':v.toFixed(2)+'×';
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const date=()=>new Date().toISOString().slice(0,10);
const safeURL=v=>{try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const link=(url,label)=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
const stages=['Research','Contact planned','NDA / information','Underwriting','Lender review','LOI review','Diligence','Closed','Passed'];
const roles=['Chair / industry adviser','Acquisition operator','Transaction attorney','Diligence CPA','Lender / capital specialist','Integration lead','Seller / broker','Potential buyer','Equity investor'];
const tasks=['Define acquisition thesis and walk-away conditions','Verify seller identity and mandate','Obtain NDA and three years of financials','Reconcile tax returns, bank deposits, and earnings adjustments','Review customer concentration, churn, contracts, and leases','Confirm working-capital peg, capex, liens, and debt-free purchase terms','Recruit operator, counsel, CPA, and industry adviser','Obtain lender feedback and documented equity commitments','Stress cash flow, balloon maturity, and integration spending','Review LOI, purchase agreement, permits, and consents','Plan first 100 days and weekly cash reporting'];
function initial(){const specs=[['Neighborhood service route',150000,65000,'Services','IL','SDE',35000],['Regional HVAC operator',750000,260000,'HVAC','TX','SDE',100000],['Recurring B2B services',2500000,700000,'Business services','IL','EBITDA',0],['Rural precision manufacturer',8000000,1800000,'Manufacturing','IA','EBITDA',0],['Regional distribution platform',20000000,3600000,'Distribution','OH','EBITDA',0],['Multi-location services platform',50000000,7500000,'Business services','US','EBITDA',0]];
 const deals=specs.map((s,i)=>({id:uid(),name:s[0],price:s[1],earnings:s[2],industry:s[3],location:s[4],metric:s[5],ownerPay:s[6],fees:Math.round(s[1]*0.04),workingCapital:Math.round(s[1]*0.05),capex:Math.round(s[2]*0.08),taxes:Math.round(s[2]*0.15),wcAnnual:Math.round(s[2]*0.04),revenue:null,rural:i===3?'Yes':'Unknown',sourceURL:'',sourceDate:date(),evidence:'Demo',demo:true,stage:'Research',notes:'Fictional scenario for testing. No actual seller, financial documents, or funding commitment.',checks:[]}));
 return {version:1,buyer:{cash:250000,external:0,minDscr:1.25},deals,contacts:[],sources:structuredClone(window.QLA_SOURCES),runs:[],outcomes:[],signals:[],selected:deals[1].id};}
let state;try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):initial();if(state.version!==1||!Array.isArray(state.deals))throw Error('Invalid saved workspace');}catch(e){state=initial();setTimeout(()=>notify('Stored workspace could not be loaded. Export before replacing any saved data. '+e.message),0);}
let page='overview',sourceFilter='All',dealFilter='',demoFilter='All',sourceQuery='',scenarioTemplate='bank',scenarioOpts={},scenarioCustom=null,serverReady=false,agents=window.QLA_AGENTS;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch(e){notify('Could not save: browser storage may be full. Export a backup now. '+e.message);return false;}}
function notify(text,ok=false){$('notice').className='notice'+(ok?' success':'');$('notice').textContent=text;}
function selected(){return state.deals.find(d=>d.id===state.selected)||state.deals[0];}
function options(items,value){return items.map(x=>{const v=typeof x==='string'?x:x.id,n=typeof x==='string'?x:x.name;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`;}).join('');}
function selectDeal(){return `<label>Selected business<select id="dealSelect">${options(state.deals,state.selected)}</select></label>`;}
function metric(label,value,sub=''){return `<div class="card"><small>${esc(label)}</small><div class="metric mono">${esc(value)}</div><span class="sub">${esc(sub)}</span></div>`;}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="empty">No records yet.</td></tr>`}</tbody></table></div>`;}
function analyze(d,t=F.templates.find(x=>x.id===scenarioTemplate),opts={}){try{return F.analyze(d,t,state.buyer,opts);}catch{return null;}}
function modelInputReason(d){const missing=numericFields.filter(k=>d[k]===''||d[k]==null||!Number.isFinite(Number(d[k])));return missing.length?'Missing or invalid: '+missing.join(', '):'Check earnings definition and cost assumptions.';}
function combos(){return state.deals.flatMap(d=>F.templates.flatMap(t=>{const m=analyze(d,t),down=analyze(d,t,{stress:.2,rateShock:2});return m?[{d,t,m,down}]:[];}));}
function goto(p){page=p;render();window.scrollTo(0,0);if(['agents','settings','intelligence'].includes(p))void refreshOllama();}
function render(){const nav=[['overview','01  Deal overview'],['deals','02  Deal pipeline'],['combinations','03  Deal & financing ranks'],['lab','04  Scenario lab'],['sources','05  Sources & discovery'],['agents','06  Agent workspace'],['team','07  Team & outreach'],['workflow','08  Full deal workflow'],['process','09  Process & learning'],['settings','10  Data & setup'],['sourcing','11  Sourcing campaigns'],['intelligence','12  Off-market intelligence']];
 $('nav').innerHTML=nav.map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${label}</button>`).join('');
 $('pageTitle').textContent=nav.find(x=>x[0]===page)[1].slice(4);$('buyerCash').value=state.buyer.cash;$('outsideCash').value=state.buyer.external;$('minDscr').value=state.buyer.minDscr;
 $('view').innerHTML=({intelligence:intelligenceView,sourcing:sourcingView,workflow:workflowView,overview:overview,deals:dealsView,combinations:combinationsView,lab:labView,sources:sourcesView,agents:agentsView,team:teamView,process:processView,settings:settingsView})[page]();
}
function overview(){const all=combos(),screen=all.filter(x=>x.m.status.startsWith('Screen')),real=state.deals.filter(d=>!d.demo);
 return `<section class="hero"><span class="pill">YOUR ACQUISITION WORKBENCH</span><h2>Explore the deal.<br>Understand the capital. Build the team.</h2><p>Compare businesses and financing structures, organize evidence, and turn your strongest hypotheses into a focused acquisition process.</p><div class="actions"><button data-page="combinations">Explore combinations →</button><button class="secondary" data-page="sources">Find opportunities</button></div></section>
 <div class="grid four">${metric('Businesses in pipeline',state.deals.length,`${real.length} real / ${state.deals.length-real.length} fictional demos`)}${metric('Modeled combinations',all.length,'8 illustrative financing templates')}${metric('Pass your numerical screen',screen.length,'Includes demos; not lender approval')}${metric('Research sources',state.sources.length,'Sources, directories, and public APIs')}</div>
 <div class="grid two"><div class="card"><h2>Start with a clear thesis</h2><p>Pick an industry you can understand and operate, define your funding capacity, and recruit advisers with relevant deal experience.</p><p class="sub">The sample pipeline spans $150K–$50M. It is a sandbox for comparing scale; it does not imply those deals can be financed with your cash.</p><button data-page="deals">Open pipeline</button></div><div class="card"><h2>Evidence before confidence</h2><p>Each deal carries an evidence label and source date. The calculator uses your explicit assumptions. AI agents help interpret evidence and plan next steps.</p><p class="sub">Government awards, surplus assets, and seller listings stay distinguishable. No messages or applications are sent by this app.</p><button class="secondary" data-page="agents">Meet the agents</button></div></div>
 <h2>Selected business</h2><div class="toolbar">${selectDeal()}<button data-page="lab">Model this deal →</button></div>${selected()?dealSummary(selected()):'<p>Add a business in the pipeline.</p>'}`;}
function dealSummary(d){return `<div class="card"><span class="pill ${d.demo?'warn':'blue'}">${d.demo?'FICTIONAL DEMO':esc(d.evidence)}</span><span class="pill">${esc(d.stage)}</span><h2>${esc(d.name)}</h2><p>${esc(d.industry)} · ${esc(d.location)} · Asking ${money(d.price)} · ${esc(d.metric)} ${money(d.earnings)}</p><p class="sub">${esc(d.notes)}</p>${d.sourceURL?link(d.sourceURL,'Source record')+' · '+esc(d.sourceDate):'<small>No source listing — illustrative data.</small>'}</div>`;}
function dealsView(){const ds=state.deals.filter(d=>(demoFilter==='All'||(demoFilter==='Real only'?!d.demo:d.demo))&&JSON.stringify([d.name,d.industry,d.location]).toLowerCase().includes(dealFilter.toLowerCase()));return `<p class="sub">Keep financial definitions and original sources with each business. Asking prices and earnings remain unverified until diligence.</p><div class="toolbar"><label>Search<input id="dealFilter" value="${esc(dealFilter)}" placeholder="Business, industry, state"></label><label>Data type<select id="demoFilter">${options(['All','Real only','Demos only'],demoFilter)}</select></label><button id="newDeal">Add business +</button></div>${table(['Business','Location / industry','Asking price','Earnings','Evidence / stage','Action'],ds.map(d=>[`${esc(d.name)}${d.demo?'<small>FICTIONAL DEMO</small>':''}`,`${esc(d.location)}<small>${esc(d.industry)}</small>`,money(d.price),`${money(d.earnings)}<small>${esc(d.metric)}</small>`,`${esc(d.evidence)}<small>${esc(d.stage)}</small>`,`<button data-edit="${esc(d.id)}" class="secondary">Edit</button> <button data-model="${esc(d.id)}">Model</button>`]))}<div id="dealEditor"></div>${researchLeadCards()}<details class="card"><summary>Import businesses from CSV or JSON</summary><p class="sub">Use the template for authorized exports. Required numeric fields cannot be blank. Missing earnings must be collected before a deal can be modeled. Imports deduplicate by source URL, or name plus location. Existing records are preserved.</p><div class="actions"><button id="dealTemplate" class="secondary">Download CSV template</button><button id="jsonTemplate" class="secondary">Download JSON template</button></div><label>Import file<input type="file" id="dealImport" accept=".csv,.json"></label></details>`;}
const numericFields=['price','earnings','fees','workingCapital','ownerPay','capex','taxes','wcAnnual'];
const labels={price:'Asking purchase price ($)',earnings:'Annual reported earnings ($)',fees:'Closing / diligence / financing fees ($)',workingCapital:'Working capital funded at close ($)',ownerPay:'Replacement-owner pay not already deducted ($/yr)',capex:'Maintenance capex ($/yr)',taxes:'Estimated cash taxes ($/yr)',wcAnnual:'Annual working-capital cash increase ($/yr)'};
function editor(d={id:'',name:'',price:0,earnings:0,fees:0,workingCapital:0,ownerPay:0,capex:0,taxes:0,wcAnnual:0,possibleRevenue:'',possibleEarningsLow:'',possibleEarningsHigh:'',industry:'',location:'',metric:'EBITDA',evidence:'Unverified',stage:'Research',rural:'Unknown',sourceURL:'',sourceDate:date(),notes:'',demo:false}){
 $('dealEditor').innerHTML=`<form id="dealForm" class="card"><h2>${d.id?'Edit':'Add'} business</h2><input name="id" type="hidden" value="${esc(d.id)}"><div class="fieldgrid"><label>Business name<input name="name" required maxlength="180" value="${esc(d.name)}"></label><label>Industry<input name="industry" required value="${esc(d.industry)}"></label><label>State / geography<input name="location" required value="${esc(d.location)}"></label>${numericFields.map(k=>`<label>${labels[k]}<input name="${k}" type="number" required min="${k==='earnings'?'-1000000000000':k==='price'?'1':'0'}" step="any" value="${d[k]??''}"></label>`).join('')}<label>Possible revenue ($/yr)<input name="possibleRevenue" type="number" min="0" step="any" value="${d.possibleRevenue??''}"></label><label>Possible low earnings ($/yr)<input name="possibleEarningsLow" type="number" min="0" step="any" value="${d.possibleEarningsLow??''}"></label><label>Possible high earnings ($/yr)<input name="possibleEarningsHigh" type="number" min="0" step="any" value="${d.possibleEarningsHigh??''}"></label><label>Earnings definition<select name="metric">${options(['EBITDA','SDE'],d.metric)}</select></label><label>Evidence label<select name="evidence">${options(['Unverified','Seller reported','Verified','Demo'],d.evidence)}</select></label><label>Stage<select name="stage">${options(stages,d.stage)}</select></label><label>Rural eligibility established?<select name="rural">${options(['Unknown','Yes','No'],d.rural)}</select></label><label>Source URL<input name="sourceURL" type="url" value="${esc(d.sourceURL)}"></label><label>Source observed date<input name="sourceDate" type="date" required value="${esc(d.sourceDate)}"></label><label class="full">Evidence / seller / assumptions notes<textarea name="notes">${esc(d.notes)}</textarea></label><label><input type="checkbox" name="demo" ${d.demo?'checked':''}> Fictional demo</label></div><p class="sub">Possible financials are a range for follow-up only; the scorer uses the required annual earnings field above. “Verified” is your manual assessment; the app cannot audit documents. Do not subtract owner pay twice if already included in EBITDA.</p><button type="submit">Save business</button></form>`;
 $('dealEditor').scrollIntoView({behavior:'smooth'});
}
let rankScope='Real only',rankMode='Best per business',rankQuery='';
function rankedCombos(){const rows=combos().filter(x=>(rankScope==='All'||(rankScope==='Real only'?!x.d.demo:x.d.demo))&&[x.d.name,x.d.industry,x.d.location].join(' ').toLowerCase().includes(rankQuery.toLowerCase())).map(x=>({...x,rank:F.rank(x.d,x.t,x.m,x.down,state.buyer)})).sort((a,b)=>a.rank.blocked-b.rank.blocked||b.rank.score-a.rank.score||a.d.name.localeCompare(b.d.name)||a.t.id.localeCompare(b.t.id));if(rankMode==='All financing scenarios')return rows;const seen=new Set();return rows.filter(x=>{if(seen.has(x.d.id))return false;seen.add(x.d.id);return true;});}
function combinationsView(){const rows=rankedCombos();return `<p>Rank businesses and illustrative financing structures using your saved buyer capacity. Scores prioritize research; they are not lender offers or approval probabilities.</p><div class="toolbar"><label>Businesses<select id="rankScope">${options(['Real only','Demos only','All'],rankScope)}</select></label><label>Compare<select id="rankMode">${options(['Best per business','All financing scenarios'],rankMode)}</select></label><label>Business, industry or location<input id="rankQuery" value="${esc(rankQuery)}"></label></div><details class="card"><summary>How the 100-point score works</summary><p>Funding fit: 25 points for the proportion of equity covered by buyer cash and assumed outside equity. Downside resilience: 30 points, full credit at your minimum DSCR across the entire stressed loan term (earnings down 20%, senior rate up 2 percentage points). Cash yield: 20 points, full credit at 20% annual cash after debt / total acquisition uses. Evidence: 15 points for your Verified label, 5 for Seller reported. Source recency: 10 points within 30 days, 5 within 90 days.</p><p>Funding gaps, failed cash coverage and unresolved program fit rank after scenarios without those flags regardless of score. Demos get no evidence or recency credit. These fixed weights are screening preferences, not empirical predictions. Outside equity and financing terms remain assumptions. Unreviewed discovery listings remain in the inbox until you supply missing financial definitions and costs.</p></details><div class="actions"><button id="exportRanks" class="secondary">Export ranked CSV</button><button data-page="sources">Pull actual listings</button></div>${rows.length?'':'<p class="card">No matching businesses ready to rank. Review listings in Sources & discovery, or choose Demos only to try the scorer.</p>'}${table(['Rank / score','Business','Financing scenario','Funding gap','Downside worst DSCR','Cash after debt','Breakdown / flags','Open'],rows.map(({d,t,m,down,rank},i)=>[`${i+1}. <strong>${rank.score}/100</strong>`,`${esc(d.name)}<small>${d.demo?'FICTIONAL DEMO':esc(d.evidence)}${d.possibleEarningsLow||d.possibleEarningsHigh?` · possible ${money(d.possibleEarningsLow||d.earnings)}–${money(d.possibleEarningsHigh||d.earnings)}`:''}</small>`,esc(t.name),money(m.gap),ratio(down.worstDscr),money(m.cashAfterDebt),`${esc(Object.entries(rank.parts).map(([k,v])=>k+': '+v).join(' / '))}<small>${esc(rank.flags.join('; ')||'Passes numerical screens; verify terms')}</small>`,`<button data-combo="${esc(d.id)}|${t.id}" class="secondary">Inspect</button>`]))}`;}
function labView(){const d=selected();if(!d)return '<p>Add a deal first.</p>';const t=scenarioCustom||F.templates.find(x=>x.id===scenarioTemplate),m=analyze(d,t,scenarioOpts);return `<div class="toolbar">${selectDeal()}<label>Financing template<select id="scenarioTemplate">${options(F.templates,scenarioTemplate)}</select></label></div>${dealSummary(d)}<form id="scenarioForm" class="card"><h2>Structure & stress assumptions</h2><div class="fieldgrid">${[['senior','Senior share of total uses (%)',t.senior*100,0,100],['seller','Seller debt share of total uses (%)',t.seller*100,0,100],['rate','Senior annual rate (%)',t.rate,0,50],['years','Senior amortization / maturity (years)',t.years,1,30],['sellerRate','Seller annual rate (%)',t.sellerRate,0,50],['sellerYears','Seller term (years)',t.sellerYears,1,30],['stress','Earnings reduction (%)',(scenarioOpts.stress||0)*100,0,100],['rateShock','Senior rate increase (percentage points)',scenarioOpts.rateShock||0,0,20],['hold','Exit after year',scenarioOpts.hold||5,1,10],['growth','Annual earnings growth (%)',(scenarioOpts.growth||0)*100,-50,50],['exitMultiple','Exit earnings multiple',scenarioOpts.exitMultiple??4,0,30],['exitFee','Exit transaction costs (%)',(scenarioOpts.exitFee??.04)*100,0,50]].map(([k,l,v,min,max])=>`<label>${l}<input name="${k}" type="number" step="${['years','sellerYears','hold'].includes(k)?'1':'any'}" min="${min}" max="${max}" required value="${v}"></label>`).join('')}<label><input name="io" type="checkbox" ${t.io?'checked':''}> Seller interest-only with balloon</label></div><button type="submit">Recalculate</button><p class="sub">${esc(t.notes)} Equity fills the remaining uses. Sources are not assumed committed. Growth changes earnings only; deductions stay constant. Exit value uses earnings one growth period beyond the final operating year.</p></form>${m?modelView(d,t,m):`<div class="notice">This deal is not scorable yet: ${esc(modelInputReason(d))}. Open Edit business and complete the required financial inputs.</div>`}`;}
function modelView(d,t,m){return `<div class="grid four">${metric('Total acquisition uses',money(m.uses),'Price + fees + initial working capital')}${metric('Equity needed',money(m.equity),`Unfunded gap ${money(m.gap)}`)}${metric('Year 1 debt coverage',ratio(m.dscr),`Worst term ${ratio(m.worstDscr)}`)}${metric('Year 1 cash after debt',money(m.cashAfterDebt),'All equity holders, before distributions')}</div><div class="grid two"><div class="card"><h2>Sources and uses</h2>${table(['Capital source','Amount'],[['Senior debt',money(m.senior)],['Seller debt',money(m.seller)],['Buyer equity',money(m.buyer)],['Outside equity needed',money(m.outsideNeeded)],['Total uses',money(m.uses)]])}<p class="sub">Buyer ownership: ${(m.ownership*100).toFixed(1)}% under a simple pro-rata equity assumption. No promote or preferred returns. Cash-on-cash for all equity: ${m.cashOnCash==null?'Undefined':(m.cashOnCash*100).toFixed(1)+'%'}.</p></div><div class="card"><h2>Screen: ${esc(m.status)}</h2><ul>${m.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}<li>Obtain lender underwriting and written term sheets; all template terms are assumptions.</li></ul><p class="sub">Cash available for debt service = earnings less replacement pay, maintenance capex, cash taxes, and annual working-capital increase.</p><button id="memoExport" class="secondary">Export deal memo</button></div></div><h2>Annual debt & cash schedule</h2>${table(['Year','Cash available for debt','Debt service','Cash after debt','DSCR','Balloon included','Ending debt'],m.schedule.map(x=>[x.year,money(x.cfads),money(x.debtService),money(x.cashAfterDebt),ratio(x.dscr),money(x.balloon),money(x.balance)]))}<div class="card"><h2>Illustrative exit · Year ${m.exit.year}</h2><div class="grid four">${metric('Enterprise value',money(m.exit.ev),'Applied to your chosen earnings metric')}${metric('Debt payoff',money(m.exit.debt),'After that year’s scheduled debt payments')}${metric('Net equity sale value',money(m.exit.netEquity),'Before exit taxes; excludes cash distributions')}${metric('Buyer sale proceeds',money(m.exit.buyerProceeds),'Pro-rata; no preferred waterfall')}</div><p class="sub">Exit debt shortfall: ${money(m.exit.shortfall)}. ${esc(d.metric)} exit multiples must be supported by comparable transactions. A platform EBITDA multiple must not be applied to owner-dependent SDE without normalizing it first.</p></div>`;}
function sourcesView(){const categories=['All',...new Set(state.sources.map(s=>s.category))];const ss=state.sources.filter(s=>(sourceFilter==='All'||s.category===sourceFilter)&&JSON.stringify(s).toLowerCase().includes(sourceQuery.toLowerCase()));return `<div class="card"><h2>Expand your opportunity pipeline</h2><p>Configure broader search, discover sourcing communities, and build your cold-call queue.</p><button data-page="sourcing">Open sourcing campaigns</button></div>${matchingAgentView()}${discoveryInbox()}<p>Use focused searches and authorized exports across marketplaces, capital directories, advisers, and government records. The source directory is extensible; adding a website does not create a scraping connector.</p><div class="toolbar"><label>Source category<select id="sourceFilter">${options(categories,sourceFilter)}</select></label><label>Filter directory<input id="sourceQuery" value="${esc(sourceQuery)}" placeholder="SBA, SaaS, broker…"></label><label>Your research keywords<input id="researchKeywords" value="${esc(selected()?.industry||'business acquisition')}" placeholder="HVAC Texas seller financing"></label><button id="searchPlan">Build search plan</button></div><div id="searchPlanOutput"></div><details class="card"><summary>Search live web & government data</summary><p class="sub">API results are saved as research signals, never automatically counted as acquisition targets or cash flow. Searches return at most 25 records. Brave and SAM require your API keys; USAspending does not. Brave submits only the search phrase, not your deal financials.</p><form id="discoveryForm"><div class="toolbar"><label>Provider<select name="provider"><option value="brave">Web search (Brave API)</option><option value="usaspending">USAspending awards</option><option value="sam">SAM.gov opportunities</option></select></label><label>Keywords<input name="query" required minlength="2" maxlength="160" placeholder="maintenance"></label><button type="submit">Fetch records</button></div></form><div id="discoveryOutput"></div></details><div class="grid">${ss.map(s=>`<article class="card sourcecard"><div><span class="pill">${esc(s.category)}</span><span class="pill ${s.access.startsWith('Live')?'blue':'warn'}">${esc(s.access)}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.notes)}</p><small>Reviewed ${esc(s.reviewed||'not yet reviewed')}</small><div class="actions">${link(s.url,'Open source ↗')}<button class="secondary" data-source="${esc(s.id)}">${s.enabled?'Disable':'Enable'}</button></div></article>`).join('')}</div><details class="card"><summary>Add another source</summary><form id="sourceForm"><div class="fieldgrid"><label>Name<input name="name" required></label><label>Category<select name="category">${options(categories.filter(x=>x!=='All'),'Deals')}</select></label><label>URL<input name="url" type="url" required></label><label class="full">Purpose and access notes<textarea name="notes" required></textarea></label></div><button type="submit">Add research source</button></form></details>${state.signals.length?`<div class="card"><h2>Saved discovery research</h2>${state.signals.slice(-5).reverse().map(s=>`<details><summary>${esc(s.at)} · ${esc(s.provider)} · ${esc(s.query)}</summary><pre>${esc(JSON.stringify(s.result,null,2))}</pre></details>`).join('')}</div>`:''}`;}
function agentsView(){return `${ollamaPanel()}<p>Eight specialist AI roles share the selected deal, calculated scenarios, source directory, contacts, and recent outcomes. Local AI requires the Node.js server and an installed Ollama model. Search links and numerical screening also work offline.</p><div class="toolbar">${selectDeal()}<button id="runScreen" class="secondary">Run rule-based screening</button></div><div id="agentOutput"></div><div class="grid two">${agents.map(a=>`<article class="card"><span class="pill">LOCAL AI · ON DEMAND</span><h2>${esc(a.name)}</h2><p class="sub">${esc(a.mission)}</p><button data-agent="${a.id}">Run ${esc(a.name)}</button></article>`).join('')}</div><h2>Recent agent runs</h2>${state.runs.length?state.runs.slice(-10).reverse().map(r=>`<details class="card"><summary>${esc(r.agent)} · ${esc(r.dealName||'Workspace')} · ${esc(r.at)}</summary><small>Engine: ${esc(r.model)}</small><pre>${esc(r.text)}</pre></details>`).join(''):'<div class="empty">No runs yet. Agent outputs will include their engine and timestamp.</div>'}`;}
function teamView(){const d=selected();return `<div class="toolbar">${selectDeal()}</div><p>Build the experienced team around the deal, then map sellers, buyers, and capital contacts. Directory presence does not establish suitability or willingness to participate.</p><div class="grid">${roles.slice(0,6).map(r=>{const matches=state.contacts.filter(c=>c.role===r);return `<div class="card"><span class="pill ${matches.length?'':'warn'}">${matches.length?'CANDIDATES RECORDED':'ROLE GAP'}</span><h3>${esc(r)}</h3><p class="sub">${matches.map(c=>esc(c.name)).join(', ')||'Use the team agent and directories to find candidates with relevant transaction and industry experience.'}</p></div>`;}).join('')}</div>${table(['Name / organization','Role','Fit evidence','Status','Source'],state.contacts.map(c=>[`${esc(c.name)}<small>${esc(c.company)}</small>`,esc(c.role),esc(c.notes),esc(c.status),link(c.url,'Profile ↗')]))}<details class="card"><summary>Add a contact</summary><form id="contactForm"><div class="fieldgrid"><label>Name<input name="name" required></label><label>Organization<input name="company"></label><label>Role<select name="role">${options(roles,roles[0])}</select></label><label>Public profile / source URL<input name="url" type="url" required></label><label>Status<select name="status">${options(['Research lead','Qualified by me','Contact planned','Conversation','Engaged','Declined'],'Research lead')}</select></label><label>Public business email (optional)<input name="email" type="email"></label><label class="full">Evidence of fit / geography / check size / conflicts<textarea name="notes" required></textarea></label></div><button type="submit">Save contact</button></form></details><div class="card"><h2>Draft outreach</h2><p class="sub">Drafts use supplied deal facts. They are not sent. Equity-investor solicitations need counsel to determine the offering route.</p><form id="draftForm"><div class="toolbar"><label>Recipient<select name="contact"><option value="">[Recipient name]</option>${options(state.contacts,'')}</select></label><label>Purpose<select name="purpose">${options(['Seller / broker inquiry','Lender fit inquiry','Team recruitment','Potential buyer fit'],'Seller / broker inquiry')}</select></label><button type="submit">Prepare draft</button></div></form><textarea id="draftText" aria-label="Editable outreach draft" placeholder="Your editable draft will appear here."></textarea><button id="draftDownload" class="secondary">Download draft</button><p class="sub">Selected business: ${esc(d?.name||'None')}</p></div>`;}
function processView(){const d=selected();return `<div class="toolbar">${selectDeal()}</div><div class="grid two"><div class="card checklist"><h2>Acquisition gates</h2><p class="sub">Checklist progress is recorded per deal. Completion is your assessment; no automated approvals.</p>${d?tasks.map((t,i)=>`<label><input type="checkbox" data-task="${i}" ${(d.checks||[]).includes(i)?'checked':''}>${esc(t)}</label>`).join(''):'Add a deal first.'}</div><div class="card"><h2>Record what happened</h2><form id="outcomeForm"><label>Outcome<select name="kind">${options(['Source useful','Source rejected','Seller replied','Lender interested','Lender declined','Diligence issue','Deal closed','Deal passed','Forecast variance'],'Source useful')}</select></label><label>Source / counterparty<input name="source" required></label><label>Evidence and lesson<textarea name="notes" required placeholder="What actually happened? What would you change next time?"></textarea></label><button type="submit">Save outcome</button></form></div></div><div class="card"><h2>Learning loop</h2><p>${state.outcomes.length} outcomes recorded. Use the Process Improvement Analyst to propose experiments based on this history. Adopt changes only after reviewing evidence; predictions are not successful outcomes.</p><button data-agent="improvement">Analyze process with local AI</button></div><div id="agentOutput"></div>${table(['Date','Deal','Outcome','Source','Lesson'],state.outcomes.slice().reverse().map(o=>[esc(o.at),esc(o.dealName),esc(o.kind),esc(o.source),esc(o.notes)]))}`;}
function settingsView(){return `${ollamaPanel()}<div class="grid two"><div class="card"><h2>Back up your workspace</h2><p>Export deals, filing dossiers, financial scenarios, sources, contacts, runs, signals, and outcomes. The backup contains any business information you entered.</p><button id="backup" class="secondary">Export JSON backup</button><label>Restore a backup (replaces this browser’s workspace)<input id="restore" type="file" accept=".json"></label><p class="sub">Existing data is not replaced until you confirm the validated import. Export first if you need to retain both workspaces.</p></div><div class="card"><h2>Local AI & government APIs</h2><p>Run <code>Start.cmd</code> and open <code>http://127.0.0.1:8765</code>. The launcher starts Ollama when needed. Choose the installed model above; <code>QLA_MODEL</code> can override the saved choice at startup.</p><p class="sub">Direct SEC filing collection and USAspending need no API key. Optional <code>QLA_SEC_USER_AGENT</code> identifies your organization/contact to SEC. <code>SAM_API_KEY</code> enables SAM.gov; <code>BRAVE_API_KEY</code> enables web discovery. API/model errors are visible and never replaced with fake results.</p><button id="health" class="secondary">Check connection</button><pre id="healthOutput">${serverReady?'Local server connected.':'Server not connected. Offline features are available.'}</pre></div></div><div class="card"><h2>Project boundaries</h2><p>Single-user local workbench with financing scenarios, specialist AI roles, direct SEC filing collection and cross-document analysis, government and web discovery, contacts, draft outreach, and outcome tracking.</p><p class="sub">Filing intelligence covers SEC reporting companies and their potential divisions/assets, not all private businesses. No continuous web crawling, automated contact sending, verified lender quotes, or closed-deal execution. Sources behind accounts need authorized exports. Actual credit and acquisition decisions require evidence and professional review.</p><button id="clearDemos" class="secondary">Remove fictional demo deals</button></div>`;}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function csv(rows){return rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s)||(/^-.+/.test(s)&&!Number.isFinite(Number(s))))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quoted CSV field');row.push(cell);if(row.some(Boolean))rows.push(row);const header=rows.shift()?.map(x=>x.trim().replace(/^\uFEFF/,''));if(!header)throw Error('CSV is empty');return rows.map(r=>Object.fromEntries(header.map((k,i)=>[k,r[i]??''])));}
function validateDeal(raw){const d={...raw};for(const k of ['name','industry','location']){if(typeof d[k]!=='string'||!d[k].trim())throw Error('Missing '+k);d[k]=d[k].trim();}for(const k of numericFields){if(d[k]===''||d[k]==null)throw Error(d.name+': missing '+k);d[k]=Number(d[k]);if(!Number.isFinite(d[k])||(k!=='earnings'&&d[k]<0))throw Error(d.name+': invalid '+k);}for(const k of ['possibleRevenue','possibleEarningsLow','possibleEarningsHigh']){if(d[k]===''||d[k]==null)d[k]='';else{d[k]=Number(d[k]);if(!Number.isFinite(d[k])||d[k]<0)throw Error(d.name+': invalid '+k);}}if(d.possibleEarningsLow!==''&&d.possibleEarningsHigh!==''&&d.possibleEarningsHigh<d.possibleEarningsLow)throw Error(d.name+': possible high earnings must be at least possible low earnings');if(d.price<=0)throw Error('Price must exceed zero');d.demo=d.demo===true||d.demo==='true';d.metric=d.metric||'EBITDA';if(!['EBITDA','SDE'].includes(d.metric))throw Error('Metric must be EBITDA or SDE');d.sourceURL=d.sourceURL||'';if(d.sourceURL&&!safeURL(d.sourceURL))throw Error('Invalid source URL');if(!d.demo&&!d.sourceURL)throw Error('Real deals require a source URL');d.sourceDate=d.sourceDate||date();d.evidence=d.demo?'Demo':['Unverified','Seller reported','Verified'].includes(d.evidence)?d.evidence:'Unverified';d.stage=stages.includes(d.stage)?d.stage:'Research';d.rural=['Yes','No','Unknown'].includes(d.rural)?d.rural:'Unknown';d.id=d.id||uid();d.notes=String(d.notes||'');d.checks=Array.isArray(d.checks)?d.checks.filter(x=>Number.isInteger(x)&&x>=0&&x<tasks.length):[];return d;}
async function api(path,body){if(location.protocol==='file:')throw Error('Open Start.cmd, then use http://127.0.0.1:8765 for AI and API searches.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),path==='/api/agent'?930000:330000);try{const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:controller.signal});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result;}finally{clearTimeout(timeout);}}
async function runAgent(id,button){const d=selected();if(!d)throw Error('Select or add a business first.');button.disabled=true;const original=button.textContent;button.textContent='Agent working…';notify('Running local AI. Loading a larger model and completing the analysis can take several minutes.');try{const r=await api('/api/agent',{agent:id,context:{deal:d,scenarios:F.templates.map(t=>({name:t.name,assumptions:t,model:analyze(d,t)})),sources:state.sources.filter(s=>s.enabled).map(({name,url,category,notes})=>({name,url,category,notes})),contacts:state.contacts,discoveryEvidence:state.signals.slice(-3),outcomes:state.outcomes.slice(-20)}});state.runs.push({...r,dealName:d.name,dealId:d.id});save();if($('agentOutput'))$('agentOutput').innerHTML=`<div class="card"><h2>${esc(r.agent)}</h2><small>Local AI · ${esc(r.model)}</small><pre>${esc(r.text)}</pre></div>`;notify('Agent analysis saved. Review its claims against the evidence.',true);}finally{button.disabled=false;button.textContent=original;}}
function screen(){const d=selected();if(!d)throw Error('Add a deal first');const cases=F.templates.map(t=>({t,m:analyze(d,t)})).filter(x=>x.m);const text=`RULE-BASED SCREEN — not AI\n${d.name} (${d.demo?'fictional demo':d.evidence})\n\n`+cases.map(({t,m})=>`${t.name}: ${m.status}; year-1 DSCR ${ratio(m.dscr)}, worst-term ${ratio(m.worstDscr)}, equity gap ${money(m.gap)}.\n${m.warnings.join(' ')}`).join('\n\n')+'\n\nNext: obtain source financials, normalize earnings, confirm owner replacement costs, recruit operator/CPA/counsel, request lender fit review.';state.runs.push({agent:'Numerical screening',model:'Deterministic finance.js v1',text,dealName:d.name,dealId:d.id,at:new Date().toISOString()});save();$('agentOutput').innerHTML=`<div class="card"><pre>${esc(text)}</pre></div>`;}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.page){goto(b.dataset.page);return;}
 if(b.dataset.matchDraft!==undefined){const row=matchingRows()[Number(b.dataset.matchDraft)];$('matchingDraft').value=matchingDraft(row);$('matchingDraft').scrollIntoView({behavior:'smooth'});return;}
 if(b.dataset.inbox!==undefined){reviewInbox(Number(b.dataset.inbox));return;}
 if(b.dataset.lead){const lead=window.QLA_RESEARCH_LEADS.find(x=>x.id===b.dataset.lead);editor({...lead,id:''});return;}
 if(b.dataset.edit){editor(state.deals.find(d=>d.id===b.dataset.edit));return;}
 if(b.dataset.model){state.selected=b.dataset.model;save();scenarioCustom=null;goto('lab');return;}
 if(b.dataset.combo){[state.selected,scenarioTemplate]=b.dataset.combo.split('|');scenarioCustom=null;scenarioOpts={};save();goto('lab');return;}
 if(b.dataset.agent){await runAgent(b.dataset.agent,b);return;}
 if(b.dataset.source){const s=state.sources.find(s=>s.id===b.dataset.source);s.enabled=!s.enabled;save();render();return;}
 switch(b.id){case 'refreshOllama':await refreshOllama();break;case 'useOllamaModel':await useOllamaModel();break;case 'saveBuyer':{const buyer={cash:Number($('buyerCash').value),external:Number($('outsideCash').value),minDscr:Number($('minDscr').value)};if(!Number.isFinite(buyer.cash)||buyer.cash<0||!Number.isFinite(buyer.external)||buyer.external<0||!Number.isFinite(buyer.minDscr)||buyer.minDscr<1||buyer.minDscr>5)throw Error('Enter nonnegative cash and a DSCR between 1 and 5.');state.buyer=buyer;save();render();notify('Buyer screening assumptions saved.',true);break;}
 case 'backupTop':case 'backup':download('qla-backup-'+date()+'.json',JSON.stringify(state,null,2));break;
 case 'newDeal':editor();break;
 case 'runScreen':screen();break;
 case 'searchPlan':{const query=$('researchKeywords').value.trim();if(!query)throw Error('Enter research keywords');const ss=state.sources.filter(s=>s.enabled&&(sourceFilter==='All'||s.category===sourceFilter));$('searchPlanOutput').innerHTML=`<div class="card"><h2>Focused listing searches · ${ss.length} sources</h2><p class="sub">These searches are narrowed toward individual listing pages. The direct action opens Google’s best match; use the fallback when it chooses a directory or category page.</p>${table(['Source','Listing-focused query','Open'],ss.map(s=>{const q='site:'+new URL(s.url).hostname+' ('+query+') ("for sale" OR listing OR acquisition) -directory -category -search -results',encoded=encodeURIComponent(q);return [esc(s.name),esc(q),link('https://www.google.com/search?btnI=1&q='+encoded,'Open best match ↗')+' '+link('https://www.google.com/search?q='+encoded,'See results')];}))}</div>`;break;}
 case 'runMatcher':await runMatchingAgent();break;
 case 'toggleMatcher':state.matcherAuto=!state.matcherAuto;save();render();if(state.matcherAuto)await runAutomaticSearches();break;
 case 'exportRanks':download('qla-ranked.csv',csv([['Rank','Score','Business','Demo','Structure','Funding gap','Downside worst DSCR','Cash after debt','Flags'],...rankedCombos().map((x,i)=>[i+1,x.rank.score,x.d.name,x.d.demo,x.t.name,x.m.gap,x.down.worstDscr,x.m.cashAfterDebt,x.rank.flags.join('; ')])]),'text/csv');break;
 case 'exportCombos':download('qla-combinations.csv',csv([['Business','Demo','Structure','Uses','Buyer equity','Outside equity needed','Equity gap','DSCR year 1','Downside DSCR','Worst DSCR','Cash after debt','Status'],...combos().map(({d,t,m,down})=>[d.name,d.demo,t.name,m.uses,m.buyer,m.outsideNeeded,m.gap,m.dscr,down.dscr,m.worstDscr,m.cashAfterDebt,m.status])]),'text/csv');break;
 case 'dealTemplate':case 'jsonTemplate':{const d={...initial().deals[0],name:'REPLACE WITH BUSINESS NAME',demo:false,sourceURL:'https://example.com/replace-with-listing',evidence:'Unverified'};delete d.id;delete d.checks;delete d.revenue;download(b.id==='dealTemplate'?'deal-template.csv':'deal-template.json',b.id==='dealTemplate'?csv([Object.keys(d),Object.values(d)]):JSON.stringify([d],null,2),b.id==='dealTemplate'?'text/csv':'application/json');break;}
 case 'memoExport':{const d=selected(),t=scenarioCustom||F.templates.find(t=>t.id===scenarioTemplate),m=analyze(d,t,scenarioOpts);download('deal-memo-'+date()+'.json',JSON.stringify({generatedAt:new Date().toISOString(),modelVersion:'finance-v1',deal:d,buyer:state.buyer,financing:t,assumptions:scenarioOpts,results:m,limitations:'Illustrative. Unverified lender terms. Exit excludes taxes and cash distributions. Simple pro-rata ownership.'},null,2));break;}
 case 'draftDownload':if(!$('draftText').value)throw Error('Prepare a draft first');download('outreach-draft.txt',$('draftText').value,'text/plain');break;
 case 'health':{const r=await api('/api/health');serverReady=true;acceptOllamaStatus(r.ollama);if($('healthOutput'))$('healthOutput').textContent=JSON.stringify(r,null,2);break;}
 case 'clearDemos':if(confirm('Remove fictional demo businesses? Export a backup first if you need them.')){state.deals=state.deals.filter(d=>!d.demo);state.selected=state.deals[0]?.id||'';save();render();}break;
 }
 }catch(err){notify(err.message);}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='rankScope'){rankScope=el.value;render();}if(el.id==='rankMode'){rankMode=el.value;render();}if(el.id==='dealSelect'){state.selected=el.value;save();scenarioCustom=null;render();}if(el.id==='scenarioTemplate'){scenarioTemplate=el.value;scenarioCustom=null;render();}if(el.id==='demoFilter'){demoFilter=el.value;render();}if(el.id==='sourceFilter'){sourceFilter=el.value;render();}if(el.dataset.task!==undefined){const d=selected(),i=Number(el.dataset.task);d.checks=d.checks||[];d.checks=el.checked?[...new Set([...d.checks,i])]:d.checks.filter(x=>x!==i);save();}if(el.id==='dealImport'){const file=el.files[0];if(!file)return;if(file.size>3000000)throw Error('Import limit is 3 MB');const text=await file.text(),raw=file.name.toLowerCase().endsWith('.csv')?parseCSV(text):JSON.parse(text);if(!Array.isArray(raw))throw Error('Expected a JSON array');const incoming=raw.map(validateDeal),keys=new Set(state.deals.map(d=>d.sourceURL||d.name.toLowerCase()+'|'+d.location.toLowerCase()));let count=0;for(const d of incoming){const key=d.sourceURL||d.name.toLowerCase()+'|'+d.location.toLowerCase();if(!keys.has(key)){d.id=uid();state.deals.push(d);keys.add(key);count++;}}if(!state.selected)state.selected=state.deals[0]?.id||'';save();render();notify(`Imported ${count}; skipped ${incoming.length-count} duplicate records.`,true);}if(el.id==='restore'){const file=el.files[0];if(!file)return;if(file.size>10000000)throw Error('Backup limit is 10 MB');const x=JSON.parse(await file.text());if(x.version!==1||!x.buyer||!Array.isArray(x.deals)||!Array.isArray(x.sources)||!Array.isArray(x.contacts)||!Array.isArray(x.runs)||!Array.isArray(x.signals)||!Array.isArray(x.outcomes))throw Error('Invalid backup structure');x.deals=x.deals.map(validateDeal);if(![x.buyer.cash,x.buyer.external,x.buyer.minDscr].every(Number.isFinite)||x.buyer.cash<0||x.buyer.external<0||x.buyer.minDscr<1||x.buyer.minDscr>5)throw Error('Invalid buyer inputs');if(!x.sources.every(s=>s&&typeof s.name==='string'&&safeURL(s.url)))throw Error('Invalid source records');if(new Set(x.deals.map(d=>d.id)).size!==x.deals.length)throw Error('Duplicate deal identifiers');if(confirm(`Replace current workspace with ${x.deals.length} businesses and ${x.contacts.length} contacts from this backup?`)){state=x;if(!state.deals.some(d=>d.id===state.selected))state.selected=state.deals[0]?.id||'';save();render();notify('Backup restored.',true);}}}catch(err){notify(err.message);el.value='';}});
document.addEventListener('input',e=>{if(e.target.id==='rankQuery'){rankQuery=e.target.value;const pos=e.target.selectionStart;render();$('rankQuery').focus();$('rankQuery').setSelectionRange(pos,pos);}if(e.target.id==='dealFilter'){dealFilter=e.target.value;const pos=e.target.selectionStart;render();$('dealFilter').focus();$('dealFilter').setSelectionRange(pos,pos);}if(e.target.id==='sourceQuery'){sourceQuery=e.target.value;const pos=e.target.selectionStart;render();$('sourceQuery').focus();$('sourceQuery').setSelectionRange(pos,pos);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,raw=Object.fromEntries(new FormData(form));try{switch(form.getAttribute('id')){
 case 'dealForm':{raw.demo=form.elements.demo.checked;const existing=state.deals.find(d=>d.id===raw.id);const d=validateDeal({...existing,...raw});const idx=state.deals.findIndex(x=>x.id===d.id);if(idx<0)state.deals.push(d);else state.deals[idx]=d;state.selected=d.id;save();render();notify('Business saved.',true);break;}
 case 'scenarioForm':{const base=F.templates.find(t=>t.id===scenarioTemplate),t={...base};for(const k of ['rate','years','sellerRate','sellerYears'])t[k]=Number(raw[k]);t.senior=Number(raw.senior)/100;t.seller=Number(raw.seller)/100;t.io=form.elements.io.checked;const o={stress:Number(raw.stress)/100,rateShock:Number(raw.rateShock),hold:Number(raw.hold),growth:Number(raw.growth)/100,exitMultiple:Number(raw.exitMultiple),exitFee:Number(raw.exitFee)/100};F.analyze(selected(),t,state.buyer,o);scenarioCustom=t;scenarioOpts=o;render();break;}
 case 'sourceForm':if(!safeURL(raw.url))throw Error('Use an HTTP or HTTPS URL');state.sources.push({...raw,id:uid(),access:'Browser / authorized import',reviewed:'Not yet reviewed',enabled:true});save();render();notify('Research source added. Use its browser search or import authorized data.',true);break;
 case 'contactForm':if(!safeURL(raw.url))throw Error('Use an HTTP or HTTPS profile URL');state.contacts.push({...raw,id:uid(),at:date()});save();render();notify('Contact saved.',true);break;
 case 'outcomeForm':state.outcomes.push({...raw,id:uid(),dealName:selected()?.name||'Workspace',dealId:selected()?.id,at:date()});save();render();notify('Outcome recorded.',true);break;
 case 'draftForm':{const d=selected();if(!d)throw Error('Select a deal');const c=state.contacts.find(c=>c.id===raw.contact),greeting=`Hello ${c?.name||'[Recipient name]'},\n\n`,facts=`I am researching ${d.demo?'an illustrative acquisition scenario involving': 'a potential acquisition of'} ${d.name} in ${d.location}. The ${d.demo?'illustrative':'reported'} asking price is ${money(d.price)} and annual ${d.metric} is ${money(d.earnings)}. These figures require verification.\n\n`;const bodies={'Seller / broker inquiry':'Would you be open to a confidential introductory discussion? If appropriate, please share your NDA process, financial package, seller transition expectations, and whether seller financing is worth discussing.','Lender fit inquiry':`I would like an initial fit discussion about acquisition financing. My modeled buyer equity capacity is ${money(state.buyer.cash)}; funding is not committed. What eligibility, equity, collateral, guarantee, debt-service, and documentation requirements should I evaluate before applying?`,'Team recruitment':`I am assembling an acquisition team and researching candidates for ${c?.role||'[role]'}. Could we discuss relevant industry experience, completed acquisitions, availability, conflicts, references, and engagement terms?`,'Potential buyer fit':'I am researching acquisition criteria in this sector for longer-term exit planning. What geography, earnings scale, operating characteristics, and documentation does your team normally evaluate? This is an exploratory inquiry, not an offer of a business or securities.'};$('draftText').value=`DRAFT — REVIEW BEFORE SENDING${d.demo?' — FICTIONAL DEMO, REPLACE DETAILS':''}\nSubject: ${raw.purpose} — ${d.industry}\n\n${greeting}${facts}${bodies[raw.purpose]}\n\nBest,\n[Your name and business contact details]`;break;}
 case 'matcherForm':{const a={};for(const [k,v] of Object.entries(raw)){a[k]=Number(v);if(k!=='ownerPay')a[k]/=100;}QLADiscovery.match([],state.buyer,a,F);state.matcherAssumptions=a;save();render();notify('Matching assumptions saved; shortlist recalculated.',true);break;}
 case 'listingForm':{const btn=form.querySelector('button');btn.disabled=true;notify('Pulling public listings...');try{const result=await api('/api/discover',raw);const merged=QLADiscovery.merge(state.inbox||[],result.records);state.inbox=merged.rows;state.signals.push({...raw,result,at:new Date().toISOString()});save();render();notify(`Fetched ${result.records.length} records; ${merged.added} new, ${result.records.length-merged.added} refreshed. ${result.scope}`,true);}finally{btn.disabled=false;}break;}
 case 'discoveryForm':{const btn=form.querySelector('button');btn.disabled=true;notify('Fetching research records from the selected provider…');try{const result=await api('/api/discover',raw);state.signals.push({...raw,result,at:new Date().toISOString()});save();$('discoveryOutput').innerHTML=`<p>${esc(result.scope)}</p><pre>${esc(JSON.stringify(result.records,null,2))}</pre>`;notify(`Saved ${result.records.length} research records. These are not businesses for sale.`,true);}finally{btn.disabled=false;}break;}
 }}catch(err){notify(err.message);}});
$('backupTop').title='Download a complete local workspace backup';
render();
if(location.protocol!=='file:')api('/api/health').then(r=>{serverReady=true;acceptOllamaStatus(r.ollama);return api('/api/agents');}).then(a=>{agents=a;if(page==='agents')render();}).catch(()=>{serverReady=false;acceptOllamaStatus({connected:false,ready:false,models:[],error:'Local server unavailable. Open Start.cmd, then refresh models.'});});

function researchLeadCards(){return '<h2>Researched public listings</h2><p class="sub">Observed September 7, 2026. Broker-reported, not independently verified. Fill missing cost assumptions before saving to the modeled pipeline.</p><div class="grid two">'+window.QLA_RESEARCH_LEADS.map(d=>'<article class="card"><span class="pill blue">PUBLIC RESEARCH LEAD</span><h3>'+esc(d.name)+'</h3><p>'+money(d.price)+' asking · '+money(d.earnings)+' reported '+esc(d.metric)+'</p><p class="sub">'+esc(d.notes)+'</p>'+link(d.sourceURL,'Original listing ↗')+'<div class="actions"><button data-lead="'+esc(d.id)+'">Review & complete inputs</button></div></article>').join('')+'</div>';}

function discoveryInbox(){const rows=state.inbox||[];return `<section class="card"><h2>Pull actual listings</h2><p>Fetch current featured listings directly from Vested Business Brokers without an API key. For broader searches, choose Brave (requires BRAVE_API_KEY on the local server). Results appear below and persist in this browser.</p><form id="listingForm"><div class="toolbar"><label>Source<select name="provider"><option value="vested">Vested: featured business listings (no key)</option><option value="brave">Brave: broader web search (API key)</option></select></label><label>Keywords for Brave<input name="query" value="business for sale seller financing" minlength="2" maxlength="160"></label><button type="submit">Pull listings now</button></div></form><p class="sub">Vested pulls its current featured page; keywords apply only to Brave. Refreshing updates existing URLs. Cash flow definitions, sale availability and seller-financing terms require confirmation. Search results can include directory pages.</p><h3>Discovery inbox (${rows.length})</h3>${table(['Listing / source','Location','Asking price','Reported cash flow','Seller financing','Status / next step'],rows.map((r,i)=>{const existing=state.deals.find(d=>QLADiscovery.canonical(d.sourceURL)===QLADiscovery.canonical(r.url));return [`${link(r.url,r.title)}<small>Observed ${esc(r.observedAt?.slice(0,10))}</small>`,esc(r.location||'Unknown'),money(r.price),money(r.reportedCashFlow),r.sellerFinancing?'Advertised; terms unverified':'Unknown',`<small>${existing?'In pipeline':'Needs information; not scored'}</small><button data-inbox="${i}" class="secondary">${existing?'Edit business':'Review & score'}</button>`];}))}</section>`;}
function reviewInbox(i){const r=state.inbox?.[i];if(!r)throw Error('Listing no longer exists');const existing=state.deals.find(d=>QLADiscovery.canonical(d.sourceURL)===QLADiscovery.canonical(r.url));goto('deals');if(existing){editor(existing);return;}const a={fees:.04,workingCapital:.05,ownerPay:75000,capex:.05,taxes:.20,wcAnnual:.03,...state.matcherAssumptions};editor({id:'',name:r.title,industry:'',location:r.location||'',price:r.price??'',earnings:r.reportedCashFlow??'',fees:r.price?Math.round(r.price*a.fees):'',workingCapital:r.price?Math.round(r.price*a.workingCapital):'',ownerPay:a.ownerPay,capex:r.reportedCashFlow?Math.round(r.reportedCashFlow*a.capex):'',taxes:r.reportedCashFlow?Math.round(r.reportedCashFlow*a.taxes):'',wcAnnual:r.reportedCashFlow?Math.round(r.reportedCashFlow*a.wcAnnual):'',possibleRevenue:r.reportedRevenue??'',possibleEarningsLow:r.reportedCashFlow?Math.round(r.reportedCashFlow*.8):'',possibleEarningsHigh:r.reportedCashFlow?Math.round(r.reportedCashFlow*1.2):'',metric:'',evidence:'Seller reported',stage:'Research',rural:'Unknown',sourceURL:r.url,sourceDate:r.observedAt?.slice(0,10)||date(),notes:`Imported from ${r.provider||'web search'}. ${r.snippet||''} Screening assumptions prefilled from the matching agent; replace them with deal-specific figures. Reported cash flow: ${money(r.reportedCashFlow)}. Advertised down payment: ${money(r.downPayment)}. Seller financing: ${r.sellerFinancing?'advertised, terms unverified':'unknown'}. Confirm the annual earnings amount and definition before relying on the score.`,demo:false});const select=document.querySelector('#dealForm [name=metric]');select.insertAdjacentHTML('afterbegin','<option value="" selected>Confirm earnings definition</option>');select.required=true;}

let matchingBusy=false;
function matchingRows(){return QLADiscovery.match(state.inbox||[],state.buyer,state.matcherAssumptions||{},F);}
function matchingAgentView(){const a={fees:.04,workingCapital:.05,ownerPay:75000,capex:.05,taxes:.20,wcAnnual:.03,...state.matcherAssumptions},rows=matchingRows();return `<section class="card"><span class="pill blue">DEAL MATCHING AGENT</span><h2>Find leads, test possibilities, prepare outreach</h2><p>Pull public broker listings and compare eight financing scenarios per listing. This rule-based agent works without an AI model. It uses provisional costs below and treats reported cash flow as an unconfirmed starting figure.</p><div class="actions"><button id="runMatcher" ${matchingBusy?'disabled':''}>Search & run possibilities</button><button id="toggleMatcher" class="secondary">${state.matcherAuto?'Stop automatic searches':'Start automatic searches'}</button></div><p class="sub">Automatic searches: ${state.matcherAuto?'ON, every 30 minutes while this app is open':'OFF'}. Last successful search: ${esc(state.matcherLast||'Not yet run')}. Browser sleep can delay searches. The source returns a changing featured sample, not every listing. All lender structures are hypothetical; seller financing advertisements are not agreed terms.</p><details><summary>Edit provisional matching assumptions</summary><form id="matcherForm"><div class="fieldgrid">${[['fees','Closing costs (% of price)'],['workingCapital','Initial working capital (% of price)'],['ownerPay','Annual operator pay ($)'],['capex','Annual capex (% of reported cash flow)'],['taxes','Cash taxes (% of reported cash flow)'],['wcAnnual','Annual working capital increase (% of reported cash flow)']].map(([k,l])=>`<label>${l}<input name="${k}" type="number" min="0" ${k==='ownerPay'?'':'max="100"'} step="any" required value="${k==='ownerPay'?a[k]:a[k]*100}"></label>`).join('')}</div><button>Save & recalculate</button></form><p class="sub">Operator pay may already be deducted from broker cash flow. Confirm its definition to avoid double counting. These assumptions are screening placeholders, not estimates verified for each business. Scores change when your buyer capacity or these costs change.</p></details><h3>Provisional shortlist</h3>${table(['Listing','Best modeled possibility','Provisional score','Result / missing evidence','Next step'],rows.map((x,i)=>[link(x.r.url,x.r.title),x.ready?`${esc(x.best.t.name)}<small>Equity gap ${money(x.best.m.gap)} / downside worst DSCR ${ratio(x.best.down.worstDscr)}</small>`:'Needs financial information',x.ready?x.best.rank.score+'/100':'Not scored',x.ready?`${x.best.rank.blocked?'Needs changes to modeled structure':'Potential fit under assumptions'}<small>${esc(x.best.rank.flags.join('; '))}; confirm earnings definition, availability and lender terms</small><details><summary>All ${x.cases.length} possibilities</summary>${table(['Structure','Score','Gap','Worst downside DSCR'],x.cases.map(c=>[esc(c.t.name),c.rank.score,money(c.m.gap),ratio(c.down.worstDscr)]))}</details>`:esc(x.reason),`<button data-match-draft="${i}" class="secondary">Prepare email / call notes</button>`]))}<label>Outreach draft ? review and send yourself<textarea id="matchingDraft" rows="12" placeholder="Choose a listing to prepare questions grounded in its source record."></textarea></label></section>`;}
function matchingDraft(x){return `Subject: Inquiry about ${x.r.title}

Hello,

I am researching the listing for ${x.r.title}${x.r.location?' in '+x.r.location:''}:
${x.r.url}

Is it still available? The listing reports an asking price of ${money(x.r.price)} and cash flow of ${money(x.r.reportedCashFlow)}. Could you explain whether cash flow means SDE, EBITDA, or something else, the reporting period, and which owner compensation and adjustments it includes?

Please share your NDA process and financial package, including revenue, tax returns, working capital needs, maintenance capex and seller transition expectations. Is seller financing available, and if so what down payment, interest, amortization, balloon and security terms would the seller consider?

Thank you,
[Your name and contact information]

--- PRIVATE CALL PREPARATION; REMOVE BEFORE SENDING ---
${x.ready?'Most promising modeled scenario: '+x.best.t.name+'. Provisional score '+x.best.rank.score+'/100; equity gap '+money(x.best.m.gap)+'; stressed worst-term DSCR '+ratio(x.best.down.worstDscr)+'. Flags: '+x.best.rank.flags.join('; ')+'.':'Financial data incomplete.'}
Confirm availability and earnings definitions first. Financing templates are not lender quotes. Do not represent assumed outside equity as committed funds.`;}
async function runMatchingAgent(){if(matchingBusy)return;matchingBusy=true;if(page==='sources')render();notify('Matching agent is fetching public listings and comparing financing possibilities...');try{const result=await api('/api/discover',{provider:'vested'}),merged=QLADiscovery.merge(state.inbox||[],result.records);state.inbox=merged.rows;state.matcherLast=new Date().toISOString();save();const rows=matchingRows(),fit=rows.filter(x=>x.ready&&!x.best.rank.blocked).length;notify(`Agent fetched ${result.records.length} listings (${merged.added} new). ${fit} provisional fits in the saved inbox; review assumptions and missing evidence.`,true);}catch(e){notify('Matching agent: '+e.message);}finally{matchingBusy=false;if(page==='sources')render();}}
async function runAutomaticSearches(){await runMatchingAgent();if(state.matcherAuto&&campaignConfig().autoWeb)await runSourceCampaign();}
setInterval(()=>{if(state.matcherAuto&&location.protocol!=='file:')runAutomaticSearches();},30*60*1000);
if(state.matcherAuto&&location.protocol!=='file:')setTimeout(runAutomaticSearches,1000);
